static void run1_8(int64_t B, int64_t m, double* restrict x0, const double* restrict c, double* restrict out1, double* restrict outm){
    const int64_t VOL = 1024;
    double* w = WORK;
    for (int64_t b=0;b<B;b++){
        const double* restrict cb = c + b*VOL;
        double* restrict o1 = out1 + b*VOL;
        double* restrict om = outm + b*VOL;
        w = x0 + b*VOL;
        const double* restrict cw = cb;
        int64_t mm = (m==0)?1:m;
        if (m==0) memcpy(om, x0 + b*VOL, VOL*8);
        for (int64_t it=1; it<=mm; it++){
            kZ_8(w);
            for (int s=0;s<8;s++) kY_8(w + s*128);
            double* restrict dst_ = (it==mm && m!=0) ? om : w;
            kX_8(w, dst_, cw);
            if (it==1) ntcopy(o1, dst_, VOL);
        }
    }
}
static void run_8(int64_t B, int64_t m, double* restrict x0, const double* restrict c, double* restrict out1, double* restrict outm){
    const int64_t VOL = 1024;
    double* restrict w4 = WORK;
    double* restrict c4 = WORK + 4096;
    int64_t b4 = (B/4)*4;
    for (int64_t g=0; g<b4; g+=4){
        pack4_8(w4, x0 + g*VOL, x0 + (g+1)*VOL, x0 + (g+2)*VOL, x0 + (g+3)*VOL);
        pack4_8(c4, c + g*VOL, c + (g+1)*VOL, c + (g+2)*VOL, c + (g+3)*VOL);
        int64_t mm = (m==0)?1:m;
        if (m==0) memcpy(outm + g*VOL, x0 + g*VOL, 4*VOL*8);
        for (int64_t it=1; it<=mm; it++){
            kZ4_8(w4); kY4_8(w4); kX4_8(w4, c4);
            if (it==1) unpack4_8(w4, out1 + g*VOL, out1 + (g+1)*VOL, out1 + (g+2)*VOL, out1 + (g+3)*VOL);
            if (it==mm && m!=0) unpack4_8(w4, outm + g*VOL, outm + (g+1)*VOL, outm + (g+2)*VOL, outm + (g+3)*VOL);
        }
    }
    if (B > b4) run1_8(B - b4, m, x0 + b4*VOL, c + b4*VOL, out1 + b4*VOL, outm + b4*VOL);
}

