static void run_64(int64_t B, int64_t m, double* restrict x0, const double* restrict c, double* restrict out1, double* restrict outm){
    const int64_t VOL = 524288;
    double* restrict w1 = WORK;
    for (int64_t b=0;b<B;b++){
        const double* restrict cb = c + b*VOL;
        double* restrict o1 = out1 + b*VOL;
        double* restrict om = outm + b*VOL;
        int64_t mm = (m==0)?1:m;
        if (m==0) memcpy(om, x0 + b*VOL, VOL*8);
        double* restrict w = w1;
        int par = 0;
        for (int64_t it=1; it<=mm; it++){
            if (it==1) {
                const double* xv = x0 + b*VOL;
                for (int g=0; g<8; g++) {
                    for (int j1=0;j1<8;j1++) { int s = g + 8*j1; kZ_64X(xv + s*8192, w + s*8736); kY_64(w + s*8736); }
                    switch(g) {
                        case 0: xs1_64_0(w + 0*8736, 69888); break;
                        case 1: xs1_64_1(w + 1*8736, 69888); break;
                        case 2: xs1_64_2(w + 2*8736, 69888); break;
                        case 3: xs1_64_3(w + 3*8736, 69888); break;
                        case 4: xs1_64_4(w + 4*8736, 69888); break;
                        case 5: xs1_64_5(w + 5*8736, 69888); break;
                        case 6: xs1_64_6(w + 6*8736, 69888); break;
                        case 7: xs1_64_7(w + 7*8736, 69888); break;
                    }
                }
            } else {
                for (int g=0; g<8; g++) {
                    int64_t gb = (par==0) ? (int64_t)g*8736 : (int64_t)g*69888;
                    int64_t gs = (par==0) ? 69888 : 8736;
                    for (int j1=0;j1<8;j1++) { double* sl = w + gb + j1*gs; kZ_64(sl); kY_64(sl); }
                    switch(g) {
                        case 0: xs1_64_0(w + gb, gs); break;
                        case 1: xs1_64_1(w + gb, gs); break;
                        case 2: xs1_64_2(w + gb, gs); break;
                        case 3: xs1_64_3(w + gb, gs); break;
                        case 4: xs1_64_4(w + gb, gs); break;
                        case 5: xs1_64_5(w + gb, gs); break;
                        case 6: xs1_64_6(w + gb, gs); break;
                        case 7: xs1_64_7(w + gb, gs); break;
                    }
                }
            }
            int lastdirect = (it==mm && m!=0);
            for (int h=0; h<8; h++) {
                int64_t hb = (par==0) ? (int64_t)8*h*8736 : (int64_t)h*8736;
                int64_t hs = (par==0) ? 8736 : 69888;
                const double* restrict gc = cb + h*8192;
                if (lastdirect) {
                    if (it!=1 && (((uintptr_t)om)&63)==0) { xs2_64_us(w + hb, om + h*8192, gc, hs, 65536, 65536); }
                    else xs2_64_u(w + hb, om + h*8192, gc, hs, 65536, 65536);
                } else if (it==1) {
                    if ((((uintptr_t)o1)&63)==0) { xs2_64_ds(w + hb, w + hb, o1 + h*8192, gc, hs, hs, 65536, 65536); }
                    else xs2_64_d(w + hb, w + hb, o1 + h*8192, gc, hs, hs, 65536, 65536);
                } else {
                    xs2_64(w + hb, w + hb, gc, hs, hs, 65536);
                }
            }
            if (lastdirect && it==1) { _mm_sfence(); ntcopy(o1, om, VOL); }
            if (it==1 && !lastdirect) _mm_sfence();
            if (lastdirect && it!=1) _mm_sfence();
            par ^= 1;
        }
    }
}

void run_size(int64_t L, int64_t B, int64_t m, double* x0, const double* c, double* out1, double* outm){
    unsigned int mxcsr_ = _mm_getcsr();
    _mm_setcsr(mxcsr_ | 0x8040u);  /* FTZ|DAZ */
    switch(L){
        case 6: run_6(B,m,x0,c,out1,outm); break;
        case 8: run_8(B,m,x0,c,out1,outm); break;
        case 13: run_13(B,m,x0,c,out1,outm); break;
        case 17: run_17(B,m,x0,c,out1,outm); break;
        case 23: run_23(B,m,x0,c,out1,outm); break;
        case 36: run_36(B,m,x0,c,out1,outm); break;
        case 45: run_45(B,m,x0,c,out1,outm); break;
        case 64: run_64(B,m,x0,c,out1,outm); break;
        default: break;
    }
    _mm_setcsr(mxcsr_);
}

void dbg_pass(int64_t L, int64_t which, double* v){
    switch(L){
        case 6:
            if (which==0) { kZ_6(v); }
            else { for (int s=0;s<6;s++) kY_6(v + s*72); }
            break;
        case 8:
            if (which==0) { kZ_8(v); }
            else { for (int s=0;s<8;s++) kY_8(v + s*128); }
            break;
        case 13:
            if (which==0) { kZ_13(v); }
            else { for (int s=0;s<13;s++) kY_13(v + s*338); }
            break;
        case 17:
            if (which==0) { kZ_17(v); }
            else { for (int s=0;s<17;s++) kY_17(v + s*578); }
            break;
        case 23:
            if (which==0) { kZ_23(v); }
            else { for (int s=0;s<23;s++) kY_23(v + s*1058); }
            break;
        case 36:
            if (which==0) { for (int s=0;s<36;s++) kZ_36(v + s*2592); }
            else { for (int s=0;s<36;s++) kY_36(v + s*2592); }
            break;
        case 45:
            if (which==0) { for (int s=0;s<45;s++) kZ_45(v + s*4050); }
            else { for (int s=0;s<45;s++) kY_45(v + s*4050); }
            break;
        case 64:
            if (which==0) { for (int s=0;s<64;s++) kZ_64(v + s*8736); }
            else { for (int s=0;s<64;s++) kY_64(v + s*8736); }
            break;
        default: break;
    }
}

void bench_kernel(int64_t L, int64_t which, double* v, double* v2, int64_t reps){
    unsigned int mxcsr_ = _mm_getcsr();
    _mm_setcsr(mxcsr_ | 0x8040u);
    switch(L){
        case 6:
            if (which==0) { for(int64_t r=0;r<reps;r++) kZ_6(v); }
            if (which==1) { for(int64_t r=0;r<reps;r++) for (int s=0;s<6;s++) kY_6(v + s*72); }
            if (which==2) { for(int64_t r=0;r<reps;r++) kX_6(v, v, v2); }
            if (which==3) { for(int64_t r=0;r<reps;r++) kZ4_6(v); }
            if (which==4) { for(int64_t r=0;r<reps;r++) kY4_6(v); }
            if (which==5) { for(int64_t r=0;r<reps;r++) kX4_6(v, v2); }
            break;
        case 8:
            if (which==0) { for(int64_t r=0;r<reps;r++) kZ_8(v); }
            if (which==1) { for(int64_t r=0;r<reps;r++) for (int s=0;s<8;s++) kY_8(v + s*128); }
            if (which==2) { for(int64_t r=0;r<reps;r++) kX_8(v, v, v2); }
            if (which==3) { for(int64_t r=0;r<reps;r++) kZ4_8(v); }
            if (which==4) { for(int64_t r=0;r<reps;r++) kY4_8(v); }
            if (which==5) { for(int64_t r=0;r<reps;r++) kX4_8(v, v2); }
            break;
        case 13:
            if (which==0) { for(int64_t r=0;r<reps;r++) kZ_13(v); }
            if (which==1) { for(int64_t r=0;r<reps;r++) for (int s=0;s<13;s++) kY_13(v + s*338); }
            if (which==2) { for(int64_t r=0;r<reps;r++) kX_13(v, v, v2); }
            if (which==3) { for(int64_t r=0;r<reps;r++) kZ4_13(v); }
            if (which==4) { for(int64_t r=0;r<reps;r++) kY4_13(v); }
            if (which==5) { for(int64_t r=0;r<reps;r++) kX4_13(v, v2); }
            break;
        case 17:
            if (which==0) { for(int64_t r=0;r<reps;r++) kZ_17(v); }
            if (which==1) { for(int64_t r=0;r<reps;r++) for (int s=0;s<17;s++) kY_17(v + s*578); }
            if (which==2) { for(int64_t r=0;r<reps;r++) kX_17(v, v, v2); }
            if (which==3) { for(int64_t r=0;r<reps;r++) kZ4_17(v); }
            if (which==4) { for(int64_t r=0;r<reps;r++) kY4_17(v); }
            if (which==5) { for(int64_t r=0;r<reps;r++) kX4_17(v, v2); }
            break;
        case 23:
            if (which==0) { for(int64_t r=0;r<reps;r++) kZ_23(v); }
            if (which==1) { for(int64_t r=0;r<reps;r++) for (int s=0;s<23;s++) kY_23(v + s*1058); }
            if (which==2) { for(int64_t r=0;r<reps;r++) kX_23(v, v, v2); }
            if (which==3) { for(int64_t r=0;r<reps;r++) kZ4_23(v); }
            if (which==4) { for(int64_t r=0;r<reps;r++) kY4_23(v); }
            if (which==5) { for(int64_t r=0;r<reps;r++) kX4_23(v, v2); }
            break;
        case 36:
            if (which==0) { for(int64_t r=0;r<reps;r++) for (int s=0;s<36;s++) kZ_36(v + s*2592); }
            if (which==1) { for(int64_t r=0;r<reps;r++) for (int s=0;s<36;s++) kY_36(v + s*2592); }
            if (which==2) { for(int64_t r=0;r<reps;r++) kX_36(v, v, v2); }
            if (which==6) { for(int64_t r=0;r<reps;r++) { xs1_36_0(v + 0*2592, 15552); xs1_36_1(v + 1*2592, 15552); xs1_36_2(v + 2*2592, 15552); xs1_36_3(v + 3*2592, 15552); xs1_36_4(v + 4*2592, 15552); xs1_36_5(v + 5*2592, 15552); } }
            if (which==7) { for(int64_t r=0;r<reps;r++) for (int h=0;h<6;h++) xs2_36(v + 6*h*2592, v + h*2592, v2 + h*2592, 2592, 15552, 15552); }
            break;
        case 45:
            if (which==0) { for(int64_t r=0;r<reps;r++) for (int s=0;s<45;s++) kZ_45(v + s*4050); }
            if (which==1) { for(int64_t r=0;r<reps;r++) for (int s=0;s<45;s++) kY_45(v + s*4050); }
            if (which==2) { for(int64_t r=0;r<reps;r++) kX_45(v, v, v2); }
            if (which==6) { for(int64_t r=0;r<reps;r++) { xs1_45_0(v + 0*4050, 36450); xs1_45_1(v + 1*4050, 36450); xs1_45_2(v + 2*4050, 36450); xs1_45_3(v + 3*4050, 36450); xs1_45_4(v + 4*4050, 36450); xs1_45_5(v + 5*4050, 36450); xs1_45_6(v + 6*4050, 36450); xs1_45_7(v + 7*4050, 36450); xs1_45_8(v + 8*4050, 36450); } }
            if (which==7) { for(int64_t r=0;r<reps;r++) for (int h=0;h<5;h++) xs2_45(v + 9*h*4050, v + h*4050, v2 + h*4050, 4050, 20250, 20250); }
            break;
        case 64:
            if (which==0) { for(int64_t r=0;r<reps;r++) for (int s=0;s<64;s++) kZ_64(v + s*8736); }
            if (which==1) { for(int64_t r=0;r<reps;r++) for (int s=0;s<64;s++) kY_64(v + s*8736); }
            if (which==2) { for(int64_t r=0;r<reps;r++) kX_64(v, v, v2); }
            if (which==6) { for(int64_t r=0;r<reps;r++) { xs1_64_0(v + 0*8736, 69888); xs1_64_1(v + 1*8736, 69888); xs1_64_2(v + 2*8736, 69888); xs1_64_3(v + 3*8736, 69888); xs1_64_4(v + 4*8736, 69888); xs1_64_5(v + 5*8736, 69888); xs1_64_6(v + 6*8736, 69888); xs1_64_7(v + 7*8736, 69888); } }
            if (which==7) { for(int64_t r=0;r<reps;r++) for (int h=0;h<8;h++) xs2_64(v + 8*h*8736, v + h*8736, v2 + h*8736, 8736, 69888, 69888); }
            break;
        default: break;
    }
    _mm_setcsr(mxcsr_);
}